import React from 'react';
import './CharacterSheet.css';

const CharacterSheet = () => {
  return (
    <div className="main-menu-bg">
      <div className="sheet-container">

        {/* Üst Bilgi Alanı */}
        <header className="sheet-header wrapper">
          <div className="char-name-section">
            <input type="text" placeholder="Character Name" className="name-input" />
          </div>
          <div className="char-details-grid">
             {/* Buraya Class, Level, Race gibi inputlar gelecek */}
             <input type="text" placeholder="Class & Level" />
             <input type="text" placeholder="Background" />
             <input type="text" placeholder="Player Name" />
          </div>
        </header>

        {/* Ana İçerik Alanı */}
        <div className="sheet-body">
          <aside className="column-left">
            <div className="wrapper">Statlar ve Skilller</div>
          </aside>

          <main className="column-center">
            <div className="wrapper">HP, AC ve Saldırılar</div>
          </main>

          <aside className="column-right">
            <div className="wrapper">Özellikler ve Hikaye</div>
          </aside>
        </div>

      </div>
    </div>
  );
};

export default CharacterSheet;
